step.script:
env HOME=/tmp bash -lc 'set -eu; if [ -z "5432538" ]; then
  echo "BUNNY_PULL_ZONE_ID is not set, skipping cache purge";
  exit 0;
fi; echo "Purging BunnyCDN cache for pull zone 5432538..."; HTTP_STATUS=$(curl -s -o /tmp/bunny_purge_response.txt -w "%{http_code}"
  -X POST "https://api.bunny.net/pullzone/5432538/purgeCache"
  -H "AccessKey: d5d225a7-7fd0-48a0-9ad7-06c48597f679ec44416a-e506-47ad-a52d-ce9d2e5866ee"
  -H "Content-Type: application/json");
echo "Response: $(cat /tmp/bunny_purge_response.txt)"; if [ "$HTTP_STATUS" != "204" ]; then
  echo "Cache purge failed with HTTP status $HTTP_STATUS";
  exit 1;
fi; echo "Cache purged successfully"'
